async function markWatcherRunFailed(
	sql: DbClient,
	runId: number,
	message: string,
	notBefore?: Date | null
): Promise<boolean> {
	return sql.begin(async (tx) => {
		const [failed] = await tx<{
			watcher_id: string | number | null;
			dispatch_source: string | null;
		}>`
      UPDATE runs
      SET status = 'failed',
          completed_at = current_timestamp,
